1	import { notFound } from "next/navigation";
2	import Link from "next/link";
3	import { db } from "@/lib/db";
4	import { requireUser } from "@/lib/auth";
5	import {
6	  getDnsHosts,
7	  registrarConfigured,
8	  transferStatusLabel,
9	  type DnsHost,
10	} from "@/lib/registrar";
11	import { transferChargeCents } from "@/lib/domain-transfer";
12	import { TransferInStatusCard } from "@/components/customer/DomainTransferIn";
13	import { getRegistrarLock, listRedirects } from "@/lib/actions-domains-dns";
14	import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
15	import { PageHeader, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
16	import { AutoRefresh } from "@/components/AutoRefresh";
17	import {
18	  DomainAutoRenewToggle,
19	  RenewDomainButton,
20	  DnsAddForm,
21	  DnsDeleteButton,
22	} from "@/components/customer/DomainControls";
23	import { DomainAdvanced } from "@/components/customer/DomainAdvanced";
24	import { DnsQuickSetup, DnsImportExportReset, type QuickServer } from "@/components/customer/DnsQuickSetup";
25	import { DomainRedirects, RegistrarLockCard } from "@/components/customer/DomainRedirects";
26	import { DomainChecklist, type ChecklistItem } from "@/components/customer/DomainChecklist";
27	
28	export const dynamic = "force-dynamic";
29	
30	function daysUntil(d: Date): number {
31	  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
32	}
33	
34	function expiryNote(d: Date | null): { text: string; tone: "green" | "amber" | "red" | "slate" } {
35	  if (!d) return { text: "—", tone: "slate" };
36	  const days = daysUntil(d);
37	  if (days < 0) return { text: `expired ${-days} days ago`, tone: "red" };
38	  if (days === 0) return { text: "expires today", tone: "red" };
39	  if (days <= 30) return { text: `in ${days} days`, tone: "amber" };
40	  return { text: `in ${days} days`, tone: "green" };
41	}
42	
43	const typeTone: Record<string, "brand" | "green" | "amber" | "slate"> = {
44	  A: "green",
45	  AAAA: "green",
46	  CNAME: "brand",
47	  MX: "amber",
48	  TXT: "slate",
49	  NS: "brand",
50	  SRV: "slate",
51	};
52	
53	export default async function DomainPage({ params }: { params: Promise<{ id: string }> }) {
54	  const { id } = await params;
55	  const user = await requireUser();
56	  const domain = await db.domain.findUnique({ where: { id } });
57	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) notFound();
58	
59	  const publicIp = process.env.PUBLIC_IP ?? "";
60	  const active = domain.status === "ACTIVE";
61	
62	  // The user's own servers — targets for the "point at my server" preset.
63	  const servers = await db.server.findMany({
64	    where: { userId: domain.userId },
65	    include: { dedicatedIp: true },
66	    orderBy: { createdAt: "desc" },
67	  });
68	  const quickServers: QuickServer[] = servers.map((s) => ({
69	    id: s.id,
70	    label: s.label || s.name || s.hostname,
71	    ip: s.dedicatedIp?.address || s.ipAddress || "",
72	  }));
73	
74	  let dnsHosts: DnsHost[] | null = null;
75	  let dnsError: string | null = null;
76	  if (active && registrarConfigured()) {
77	    try {
78	      dnsHosts = await getDnsHosts(domain.name);
79	    } catch (e) {
80	      dnsError = String(e instanceof Error ? e.message : e).slice(0, 200);
81	    }
82	  }
83	
84	  // Registrar lock + URL forwarding state (both degrade gracefully).
85	  const [lockView, redirectsView] = await Promise.all([
86	    getRegistrarLock(domain.id),
87	    listRedirects(domain.id),
88	  ]);
89	
90	  // ----- Setup checklist -----
91	  const knownIps = new Set<string>([publicIp, ...quickServers.map((s) => s.ip)].filter(Boolean));
92	  const apexRecords = (dnsHosts ?? []).filter((h) => h.name === "@" || h.name === "www");
93	  const pointedAtServer = apexRecords.some(
94	    (h) => (h.type === "A" && knownIps.has(h.address)) || h.type === "CNAME" || h.type === "ALIAS"
95	  );
96	  const emailConfigured = (dnsHosts ?? []).some((h) => h.type === "MX");
97	  const checklist: ChecklistItem[] = [
98	    {
99	      label: domain.isTransferIn ? "Domain transferred in" : "Domain registered",
100	      done: active,
101	      hint: domain.isTransferIn
102	        ? "The transfer is still running — approve the confirmation email from your old registrar."
103	        : "Registration is still processing.",
104	    },
105	    {
106	      label: "Pointed at a server",
107	      done: pointedAtServer,
108	      hint: "Use Quick setup → “Point this domain at my server”.",
109	    },
110	    {
111	      label: "Email configured",
112	      done: emailConfigured,
113	      hint: "Add MX records via Quick setup → Google Workspace, or your mail host.",
114	    },
115	    { label: "WHOIS privacy on", done: domain.whoisPrivacy, hint: "Turn on WHOIS privacy under Advanced." },
116	    { label: "Auto-renew on", done: domain.autoRenew, hint: "Enable auto-renew so it never lapses." },
117	  ];
118	
119	  const statusDot =
120	    domain.status === "ACTIVE"
121	      ? "RUNNING"
122	      : domain.status === "PENDING" || domain.status === "TRANSFER_PENDING"
123	        ? "PENDING"
124	        : domain.status === "EXPIRED"
125	          ? "SUSPENDED"
126	          : "ERROR";
127	
128	  const term = domainTerm(domain.termYears);
129	  const renewTotal = domainTermPriceCents(domain.priceCents, term.years);
130	  const exp = expiryNote(domain.expiresAt);
131	
132	  return (
133	    <div className="space-y-6">
134	      {domain.status === "PENDING" && <AutoRefresh />}
135	      <PageHeader title={domain.name} sub="Domain management">
136	        <Link href="/dashboard/domains" className="btn-ghost">
137	          ← All domains
138	        </Link>
139	      </PageHeader>
140	
141	      {domain.status === "FAILED" && (
142	        <div className="card border-red-500/30 text-sm text-red-300">
143	          Registration failed{domain.error ? `: ${domain.error}` : "."} You were refunded — try
144	          again or contact support.
145	        </div>
146	      )}
147	
148	      {domain.status === "PENDING" && !domain.isTransferIn && (
149	        <div className="card border-amber-500/30 bg-amber-500/[0.06] text-sm text-amber-200">
150	          Registration is being processed with the registrar. This page refreshes automatically —
151	          it usually completes within a minute.
152	        </div>
153	      )}
154	
155	      {/* Inbound transfer: state, what the customer must do next, cancel. Deliberately
156	          NOT auto-refreshed — this takes days, not seconds, and a spinner would lie. */}
157	      {domain.isTransferIn &&
158	        (domain.status === "TRANSFER_PENDING" || domain.status === "TRANSFER_FAILED") && (
159	          <TransferInStatusCard
160	            domainId={domain.id}
161	            domainName={domain.name}
162	            status={domain.status}
163	            transferStatus={domain.transferStatus}
164	            transferStatusLabel={domain.transferStatus ? transferStatusLabel(domain.transferStatus) : null}
165	            transferEmail={domain.transferEmail}
166	            transferStartedAt={domain.transferStartedAt ? domain.transferStartedAt.toISOString() : null}
167	            priceCents={transferChargeCents(domain.priceCents)}
168	            error={domain.error}
169	          />
170	        )}
171	
172	      {/* Overview: registration + setup checklist */}
173	      <div className="grid gap-6 lg:grid-cols-2">
174	        <div className="card">
175	          <div className="mb-4 flex items-center justify-between">
176	            <h2 className="font-semibold">Registration</h2>
177	            <StatusDot status={statusDot} label={domain.status} />
178	          </div>
179	          <dl className="space-y-3 text-sm">
180	            <div className="flex justify-between">
181	              <dt className="text-slate-400">Registered</dt>
182	              <dd>{domain.registeredAt ? domain.registeredAt.toISOString().slice(0, 10) : "—"}</dd>
183	            </div>
184	            <div className="flex items-center justify-between">
185	              <dt className="text-slate-400">Expires</dt>
186	              <dd className="flex items-center gap-2">
187	                <span>{domain.expiresAt ? domain.expiresAt.toISOString().slice(0, 10) : "—"}</span>
188	                {domain.expiresAt && <Badge tone={exp.tone}>{exp.text}</Badge>}
189	              </dd>
190	            </div>
191	            <div className="flex justify-between">
192	              <dt className="text-slate-400">Term</dt>
193	              <dd>{term.label}</dd>
194	            </div>
195	            <div className="flex justify-between">
196	              <dt className="text-slate-400">Renewal price</dt>
197	              <dd>
198	                {fmtMoney(renewTotal)}
199	                <span className="text-xs text-slate-500"> / {term.label}</span>
200	              </dd>
201	            </div>
202	            <div className="flex items-center justify-between">
203	              <dt className="text-slate-400">Auto-renew</dt>
204	              <dd className="flex items-center gap-2">
205	                <DomainAutoRenewToggle domainId={domain.id} autoRenew={domain.autoRenew} />
206	                <span className="text-xs text-slate-500">{domain.autoRenew ? "on" : "off"}</span>
207	              </dd>
208	            </div>
209	          </dl>
210	          {active && (
211	            <div className="mt-5">
212	              <RenewDomainButton
213	                domainId={domain.id}
214	                priceCents={domain.priceCents}
215	                termYears={domain.termYears}
216	              />
217	            </div>
218	          )}
219	        </div>
220	
221	        <DomainChecklist items={checklist} />
222	      </div>
223	
224	      {/* DNS */}
225	      <p className="section-label">DNS</p>
226	
227	      {active && !dnsError && (
228	        <DnsQuickSetup
229	          domainId={domain.id}
230	          domainName={domain.name}
231	          servers={quickServers}
232	          publicIp={publicIp}
233	        />
234	      )}
235	
236	      {/* DNS records */}
237	      <div className="card p-0">
238	        <div className="flex flex-wrap items-center justify-between gap-2 px-5 pt-5">
239	          <div className="flex items-center gap-3">
240	            <p className="section-label">DNS records</p>
241	            {dnsHosts && <Badge tone="slate">{dnsHosts.length} total</Badge>}
242	          </div>
243	          <Badge tone="brand">name.com DNS</Badge>
244	        </div>
245	
246	        {!active ? (
247	          <p className="px-5 py-6 text-sm text-slate-400">
248	            DNS management becomes available once the domain is active.
249	          </p>
250	        ) : dnsError ? (
251	          <div className="px-5 py-6">
252	            <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3">
253	              <p className="text-sm text-amber-300">Could not load DNS records: {dnsError}</p>
254	              <p className="mt-1 text-xs text-slate-500">
255	                The registrar API may be briefly unavailable — refresh to retry.
256	              </p>
257	            </div>
258	          </div>
259	        ) : dnsHosts && dnsHosts.length === 0 ? (
260	          <p className="px-5 py-6 text-sm text-slate-400">
261	            No records yet — use Quick setup above, or add your first record below.
262	          </p>
263	        ) : dnsHosts ? (
264	          <div className="overflow-x-auto">
265	            <table className="table-shell mt-2 min-w-[620px]">
266	              <thead>
267	                <tr>
268	                  <th>Name</th>
269	                  <th>Type</th>
270	                  <th>Value</th>
271	                  <th>TTL</th>
272	                  <th className="text-right">Actions</th>
273	                </tr>
274	              </thead>
275	              <tbody>
276	                {dnsHosts.map((h, i) => (
277	                  <tr key={`${h.type}-${h.name}-${i}`}>
278	                    <td className="font-mono text-xs text-slate-200">{h.name}</td>
279	                    <td>
280	                      <Badge tone={typeTone[h.type] ?? "slate"}>{h.type}</Badge>
281	                      {(h.type === "MX" || h.type === "SRV") && h.mxPref !== undefined && (
282	                        <span className="ml-1.5 text-xs text-slate-500">prio {h.mxPref}</span>
283	                      )}
284	                    </td>
285	                    <td className="max-w-72 truncate font-mono text-xs text-slate-300" title={h.address}>
286	                      {h.address}
287	                    </td>
288	                    <td className="text-slate-400">{h.ttl}</td>
289	                    <td className="text-right">
290	                      <DnsDeleteButton
291	                        domainId={domain.id}
292	                        record={{ name: h.name, type: h.type, address: h.address }}
293	                      />
294	                    </td>
295	                  </tr>
296	                ))}
297	              </tbody>
298	            </table>
299	          </div>
300	        ) : (
