339	export function DnsImportExportReset({
340	  domainId,
341	  publicIp,
342	}: {
343	  domainId: string;
344	  publicIp: string;
345	}) {
346	  const [text, setText] = useState("");
347	  const [importResult, setImportResult] = useState<BulkResult | null>(null);
348	  const [resetResult, setResetResult] = useState<BulkResult | null>(null);
349	  const [importing, startImport] = useTransition();
350	  const [resetting, startReset] = useTransition();
351	
352	  function runImport() {
353	    startImport(async () => {
354	      setImportResult(null);
355	      const res = await importDnsRecords(domainId, text);
356	      setImportResult(res);
357	      if (!res.error) setText("");
358	    });
359	  }
360	
361	  function runReset() {
362	    const phrase = window.prompt(
363	      "This removes ALL A/AAAA/CNAME/TXT/MX/SRV records and restores a default set" +
364	        (publicIp ? ` pointing at ${publicIp}` : "") +
365	        ".\n\nType RESET to confirm."
