12	/**
13	 * SSL certificate manager for /dashboard/ssl.
14	 *
15	 * Replaces SslManager, whose table could not tell the truth about a certificate:
16	 * it rendered `expiresAt` as a bare date with no notion of whether that date had
17	 * passed (an expired cert kept a green pulsing ACTIVE dot while every visitor got
18	 * NET::ERR_CERT_DATE_INVALID), showed a mid-issuance row as the grey STOPPED dot,
19	 * gave a queued request no explanation at all — one sat "pending" for 13 minutes
20	 * behind another tenant's MIGRATE with nothing on screen to say so — and hard-
21	 * disabled Delete on any ISSUING row, stranding rows a worker restart had
22	 * orphaned.
23	 *
24	 * Every status here is derived from an observed value: `expiresAt` is the
25	 * notAfter read off the certificate (by openssl on the box at issuance, then by a
26	 * TLS read-back of :443 in the renewal sweep), and `lastError` on a non-FAILED
27	 * row means "the certificate exists but something about it is wrong" — most often
28	 * that certbot obtained it in standalone mode and nothing installed it.
29	 */
30	
31	/** Where a still-unfinished request sits in the platform's single serial queue. */
32	export type QueueInfo = {
33	  /** running = certbot is executing; queued = waiting its turn; none = no job at all. */
34	  state: "running" | "queued" | "none";
35	  /** 1 = next to run. Only meaningful when state === "queued". */
36	  position: number;
37	  aheadCount: number;
38	  queuedAtIso: string;
39	  /** The job holding the worker right now, if any. */
40	  blocking: { type: string; mine: boolean } | null;
41	};
