43	export type CertRow = {
44	  id: string;
45	  domain: string;
46	  status: string;
47	  issuer: string;
48	  autoRenew: boolean;
49	  serverName: string | null;
50	  issuedAt: string | null;
51	  /** The observed notAfter. Never a computed guess — null means "not verified". */
52	  expiresAt: string | null;
53	  lastError: string | null;
54	  queue: QueueInfo | null;
55	};
