81	const JOB_LABELS: Record<string, string> = {
82	  MIGRATE: "server migration",
83	  PROVISION: "server build",
84	  REINSTALL: "OS reinstall",
85	  RESIZE: "server resize",
86	  DISK_EXPAND: "disk expansion",
