405	              waiting for earlier platform work to finish. Jobs run strictly one at a time, so this is a
406	              wait, not a failure — the position below updates on its own.
407	            </p>
408	          </div>
409	        </div>
410	      )}
411	
412	      {certificates.length === 0 ? (
413	        <div className="card p-8 text-center text-sm text-slate-400">
414	          No certificates yet. Request one above to enable HTTPS on a domain pointed at your server.
415	        </div>
416	      ) : (
417	        <div className="card overflow-x-auto p-0">
418	          <table className="table-shell">
419	            <thead>
420	              <tr>
421	                <th>Domain</th>
422	                <th>Server</th>
423	                <th>Status</th>
424	                <th>Expires (observed)</th>
425	                <th>Auto-renew &amp; actions</th>
426	              </tr>
427	            </thead>
428	            <tbody>
429	              {certificates.map((c) => (
430	                <tr key={c.id}>
431	                  <td className="max-w-sm font-medium text-slate-100">
432	                    {c.domain}
433	                    {c.lastError && (
434	                      <span
435	                        className={`mt-0.5 block text-xs font-normal ${
436	                          c.status === "FAILED" ? "text-red-400" : "text-amber-400"
437	                        }`}
438	                      >
439	                        {c.lastError}
440	                      </span>
441	                    )}
442	                  </td>
443	                  <td className="text-slate-400">{c.serverName ?? "—"}</td>
444	                  <td>
445	                    <StatusCell c={c} />
446	                  </td>
447	                  <td className="text-slate-400">
448	                    {c.expiresAt ? (
449	                      fmtDate(c.expiresAt)
450	                    ) : (
451	                      <span className="text-slate-500">not verified</span>
452	                    )}
453	                  </td>
454	                  <td>
455	                    <CertActions cert={c} />
456	                  </td>
457	                </tr>
458	              ))}
459	            </tbody>
460	          </table>
461	        </div>
462	      )}
463	
464	      <p className="text-xs text-slate-500">
465	        Expiry dates are read from the certificate itself — at issuance, and again from what your
466	        domain actually serves on port 443. A certificate is only shown as active once a real expiry
467	        date has been observed.
468	      </p>
469	    </div>
470	  );
471	}
