10	/**
11	 * Shared "Connect Cloudflare" control, used by every DNS surface (Business Email
12	 * records, control-panel Websites, post-migration cutover, Settings).
13	 *
14	 * One button, no copy-pasting: it sends the customer to Cloudflare's own consent
15	 * screen and — because the intent rides along — the records they asked for are
16	 * created the moment they come back. Pasting an API token still works but is
17	 * demoted to an "Advanced" disclosure for people who prefer it (or whose account
18	 * predates the OAuth client being registered).
19	 */
20	
21	export type CfIntentKind = "settings" | "email" | "website" | "migration";
22	
23	/**
24	 * Cloudflare's cloud mark, inlined. Exported so every "Connect Cloudflare"
25	 * affordance shows the same logo. Inline rather than an <img>: the app's CSP
26	 * blocks third-party asset hosts, and a silently-broken logo on a trust-critical
27	 * "sign in with" button is worse than none. Kept in Cloudflare's own orange —
28	 * a recoloured brand mark reads as a knock-off and undercuts the trust the logo
29	 * is there to provide.
30	 */
31	export function CloudflareMark({ className }: { className?: string }) {
32	  return (
33	    <svg
34	      viewBox="0 0 24 24"
35	      className={className}
36	      fill="#F6821F"
37	      aria-hidden="true"
38	      focusable="false"
39	    >
40	      <path d="M16.5088 16.8447c.1475-.5068.0908-.9707-.1553-1.3154-.2246-.3164-.6016-.5-1.0605-.5205l-8.6895-.1123a.1745.1745 0 01-.1367-.0713.1673.1673 0 01-.0195-.1523c.0205-.0517.0703-.0888.125-.0937l8.7676-.1123c1.0398-.0479 2.1668-.8907 2.5625-1.9219l.499-1.3018a.2854.2854 0 00.0147-.1728C18.0234 7.7256 15.7754 6 13.1191 6c-2.4492 0-4.5293 1.4648-5.4062 3.5205-.5674-.4238-1.2891-.6504-2.0684-.5742-1.3877.1377-2.5 1.2505-2.6377 2.6382-.0352.3584-.0088.7031.0703 1.0264C.8926 12.665 0 13.5811 0 14.7051c0 .1015.0068.2011.0205.2988a.1712.1712 0 00.1699.1474h16.0332c.0908 0 .1748-.0654.2012-.1552l.084-.2514z" />
41	    </svg>
