106	/**
107	 * Connect state + connect controls. When connected it simply renders `children`
108	 * (the surface's own action, e.g. "Point DNS at this server"); when not, it shows
109	 * the Connect button and the advanced token fallback.
110	 */
111	export function CloudflareConnect({
112	  intent,
113	  id,
114	  host,
115	  next,
116	  connectedHint,
117	  onConnected,
118	  what,
119	  children,
120	  compact,
121	}: {
122	  intent: CfIntentKind;
123	  id?: string;
124	  host?: string;
125	  /** Dashboard path to return to after consent. */
126	  next: string;
127	  /** Optional first-paint value so the panel doesn't flicker. */
128	  connectedHint?: boolean;
129	  onConnected?: () => void;
130	  /** What we'll do once connected, e.g. "create these mail records". */
131	  what?: string;
132	  children?: ReactNode;
133	  compact?: boolean;
134	}) {
135	  const [status, setStatus] = useState<CloudflareStatus | null>(null);
136	  const [token, setToken] = useState("");
137	  const [error, setError] = useState<string | null>(null);
138	  const [saving, startSave] = useTransition();
139	
140	  useEffect(() => {
141	    let cancelled = false;
142	    getCloudflareStatus()
143	      .then((s) => {
144	        if (!cancelled) setStatus(s);
145	      })
146	      .catch(() => {
147	        /* leave the hint in place */
148	      });
149	    return () => {
150	      cancelled = true;
151	    };
152	  }, []);
153	
154	  const connected = status?.connected ?? connectedHint ?? false;
155	  const oauthAvailable = status?.oauthAvailable ?? true;
156	
157	  function connectWithToken() {
158	    const t = token.trim();
159	    if (!t) {
160	      setError("Paste your Cloudflare API token.");
161	      return;
162	    }
163	    setError(null);
164	    startSave(async () => {
165	      const res = await connectCloudflareToken(t);
166	      if (res?.error) {
167	        setError(res.error);
168	        return;
169	      }
170	      setToken("");
171	      setStatus((s) => (s ? { ...s, connected: true, kind: "token" } : s));
172	      onConnected?.();
173	    });
174	  }
175	
176	  if (connected) {
177	    return (
178	      <div className={compact ? "" : "space-y-2"}>
179	        {!compact && (
180	          <p className="text-xs text-emerald-300">
181	            Cloudflare is connected
182	            {status?.kind === "token" ? " (API token)" : ""}.
183	          </p>
184	        )}
185	        {children}
186	      </div>
187	    );
188	  }
189	
190	  return (
191	    <div className="space-y-2">
192	      {error && (
193	        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
194	          {error}
195	        </div>
196	      )}
197	
198	      {oauthAvailable ? (
199	        <>
200	          <a
201	            className="btn-primary inline-flex items-center gap-2 py-1.5 text-sm"
202	            href={cloudflareStartHref({ intent, id, host, next })}
203	          >
204	            <CloudflareMark className="h-4 w-4 flex-none" />
205	            Connect Cloudflare
206	          </a>
207	          <p className="text-xs text-slate-400">
208	            Sign in at Cloudflare and approve access — we only ask to{" "}
209	            {status?.scopeSummary ?? "read your zones and edit DNS records"}, and we only touch the
210	            records you ask us to.
211	            {what ? ` We'll ${what} as soon as you're back.` : ""}
212	          </p>
213	        </>
214	      ) : (
215	        <p className="text-xs text-slate-400">
216	          Cloudflare sign-in isn&apos;t set up on this server yet — paste an API token below instead.
217	        </p>
218	      )}
219	
220	      <details className="group">
221	        <summary className="cursor-pointer text-xs text-slate-500 hover:text-slate-300">
222	          Advanced: paste an API token instead
223	        </summary>
224	        <div className="mt-2">
225	          <p className="text-xs text-slate-400">
226	            Create a token scoped to{" "}
227	            <span className="font-medium text-slate-200">Zone → DNS → Edit</span> (Cloudflare → My
228	            Profile → API Tokens → Create Token → Edit zone DNS). It&apos;s stored encrypted and used
229	            only to publish the records you ask for.
230	          </p>
231	          <div className="mt-2 flex flex-wrap items-end gap-2">
232	            <div className="min-w-0 flex-1">
233	              <label className="label">Cloudflare API token</label>
234	              <input
235	                className="input"
236	                type="password"
237	                value={token}
238	                onChange={(e) => setToken(e.target.value)}
239	                placeholder="Paste token"
240	                autoCapitalize="none"
241	                autoCorrect="off"
242	                spellCheck={false}
243	              />
244	            </div>
245	            <button className="btn-secondary py-1.5 text-sm" onClick={connectWithToken} disabled={saving}>
246	              {saving ? "Connecting…" : "Use token"}
247	            </button>
248	          </div>
249	        </div>
250	      </details>
251	    </div>
252	  );
253	}
